// parse_act.mjs — hand-rolled parser for the statute interchange markup.
// Tags: act, sec, sub, h, p. Attributes double-quoted. No self-closing tags.
// Text is only legal inside <h>/<p>. No dependencies, no regex shortcuts.

export class ActParseError extends Error {
  constructor(message, line) {
    super(`Line ${line}: ${message}`);
    this.name = 'ActParseError';
    this.line = line;
  }
}

const TAGS = ['act', 'sec', 'sub', 'h', 'p'];
const REQUIRED_ATTRS = { act: ['id'], sec: ['n'], sub: ['n'], h: [], p: [] };
const MAX_SUB_DEPTH = 3;

// ---------------------------------------------------------------------------
// Tokenizer: emits { type: 'open'|'close', name, attrs, line } and
// { type: 'text', text, line }. Pure character scanning, 1-indexed lines.
// ---------------------------------------------------------------------------
function tokenize(src) {
  const tokens = [];
  let i = 0;
  let line = 1;

  const skipWs = () => {
    while (i < src.length && /\s/.test(src[i])) {
      if (src[i] === '\n') line++;
      i++;
    }
  };

  while (i < src.length) {
    if (src[i] === '<') {
      let j = i + 1;
      let closing = false;
      if (src[j] === '/') {
        closing = true;
        j++;
      }
      let name = '';
      while (j < src.length && /[A-Za-z]/.test(src[j])) name += src[j++];
      if (!name) {
        throw new ActParseError(
          closing ? 'malformed closing tag: missing tag name' : 'malformed tag: missing tag name',
          line
        );
      }
      const attrs = {};
      if (closing) {
        skipWs();
        if (src[j] !== '>') {
          throw new ActParseError(`malformed closing tag </${name}>`, line);
        }
        j++;
      } else {
        for (;;) {
          skipWs();
          if (j >= src.length) throw new ActParseError(`unterminated <${name}> tag`, line);
          if (src[j] === '>') {
            j++;
            break;
          }
          let attrName = '';
          while (j < src.length && /[A-Za-z_-]/.test(src[j])) attrName += src[j++];
          if (!attrName) throw new ActParseError(`malformed attribute in <${name}>`, line);
          skipWs();
          if (src[j] !== '=') {
            throw new ActParseError(`attribute "${attrName}" is missing "=" in <${name}>`, line);
          }
          j++;
          skipWs();
          if (src[j] !== '"') {
            throw new ActParseError(
              `attribute "${attrName}" value must be double-quoted in <${name}>`,
              line
            );
          }
          j++;
          let value = '';
          while (j < src.length && src[j] !== '"') {
            if (src[j] === '\n') line++;
            value += src[j++];
          }
          if (src[j] !== '"') {
            throw new ActParseError(`attribute "${attrName}" value is not terminated`, line);
          }
          j++;
          attrs[attrName] = value;
        }
      }
      tokens.push({ type: closing ? 'close' : 'open', name, attrs, line });
      i = j;
    } else {
      const startLine = line;
      let text = '';
      while (i < src.length && src[i] !== '<') {
        if (src[i] === '\n') line++;
        text += src[i++];
      }
      tokens.push({ type: 'text', text, line: startLine });
    }
  }
  return tokens;
}

// ---------------------------------------------------------------------------
// Parser: stack-based; produces
//   containers: { tag, attrs, children: [...] }
//   leaves:     { tag: 'h'|'p', text }
// ---------------------------------------------------------------------------
export function parseAct(src) {
  const tokens = tokenize(src);
  let root = null;
  const stack = []; // open container nodes

  const top = () => stack[stack.length - 1];

  for (const tok of tokens) {
    if (tok.type === 'open') {
      if (!TAGS.includes(tok.name)) {
        throw new ActParseError(`unknown tag <${tok.name}>`, tok.line);
      }
      if (!root) {
        if (tok.name !== 'act') {
          throw new ActParseError(`document must start with <act>, got <${tok.name}>`, tok.line);
        }
      } else if (stack.length === 0) {
        throw new ActParseError(`unexpected <${tok.name}> after root </act>`, tok.line);
      }
      const parent = top();
      if (parent && (parent.tag === 'h' || parent.tag === 'p')) {
        throw new ActParseError(`<${tok.name}> is not permitted inside <${parent.tag}>`, tok.line);
      }

      for (const req of REQUIRED_ATTRS[tok.name]) {
        if (!(req in tok.attrs)) {
          throw new ActParseError(`<${tok.name}> is missing required attribute "${req}"`, tok.line);
        }
      }
      for (const attr of Object.keys(tok.attrs)) {
        if (!REQUIRED_ATTRS[tok.name].includes(attr)) {
          throw new ActParseError(`unexpected attribute "${attr}" on <${tok.name}>`, tok.line);
        }
      }

      if (tok.name === 'sub') {
        const depth = stack.filter((n) => n.tag === 'sub').length + 1;
        if (depth > MAX_SUB_DEPTH) {
          throw new ActParseError(
            `<sub> nesting exceeds maximum depth of ${MAX_SUB_DEPTH}`,
            tok.line
          );
        }
      }

      let node;
      if (tok.name === 'h' || tok.name === 'p') {
        node = { tag: tok.name, text: '', line: tok.line };
      } else {
        node = { tag: tok.name, attrs: tok.attrs, children: [], line: tok.line };
      }

      if (!root) {
        root = node;
      } else {
        parent.children.push(node);
      }
      if (node.children) stack.push(node);
    } else if (tok.type === 'close') {
      const cur = top();
      if (!cur) {
        throw new ActParseError(`stray closing tag </${tok.name}> with nothing open`, tok.line);
      }
      if (cur.tag !== tok.name) {
        throw new ActParseError(
          `mismatched closing tag </${tok.name}>, expected </${cur.tag}>`,
          tok.line
        );
      }
      if (cur.tag === 'h' || cur.tag === 'p') {
        cur.text = cur.text.trim();
      }
      stack.pop();
    } else {
      // text token
      const cur = top();
      if (!cur) {
        if (tok.text.trim() !== '') {
          throw new ActParseError('text is not permitted outside <act>', tok.line);
        }
        continue;
      }
      if (cur.tag === 'h' || cur.tag === 'p') {
        cur.text += tok.text;
      } else if (tok.text.trim() !== '') {
        throw new ActParseError(
          `text is only permitted inside <h> or <p>, found inside <${cur.tag}>`,
          tok.line
        );
      }
    }
  }

  if (!root) throw new ActParseError('no <act> element found', 1);
  if (stack.length > 0) {
    const deepest = stack[stack.length - 1];
    throw new ActParseError(`unclosed <${deepest.tag}>`, deepest.line);
  }
  return root;
}

// ---------------------------------------------------------------------------
// toText(tree): numbered plain-text rendering.
//   Sections:   "1. Heading"
//   Paragraphs: flush under their parent
//   Subs:       "(a)", "(i)", "(A)" per nesting level, indented 2 spaces/level
// ---------------------------------------------------------------------------
function roman(n) {
  const table = [[10, 'x'], [9, 'ix'], [5, 'v'], [4, 'iv'], [1, 'i']];
  let out = '';
  for (const [v, sym] of table) {
    while (n >= v) {
      out += sym;
      n -= v;
    }
  }
  return out;
}

const SUB_LABELS = [
  (k) => String.fromCharCode(96 + k), // a, b, c
  (k) => roman(k),                    // i, ii, iii
  (k) => String.fromCharCode(64 + k), // A, B, C
];

function renderBlock(node, depth, out) {
  const indent = '  '.repeat(depth);
  if (node.tag === 'p') {
    out.push(indent + node.text);
    return;
  }
  if (node.tag === 'sub') {
    const k = (this._n = (this._n || 0) + 1); // placeholder, replaced below
    void k;
  }
}

function renderChildren(children, depth, counters, out) {
  for (const node of children) {
    if (node.tag === 'h') continue; // headings rendered by their parent level
    if (node.tag === 'p') {
      out.push('  '.repeat(depth) + node.text);
    } else if (node.tag === 'sub') {
      counters.sub = (counters.sub || 0) + 1;
      const labeler = SUB_LABELS[Math.min(depth, SUB_LABELS.length - 1)];
      out.push('  '.repeat(depth) + `(${labeler(counters.sub)})`);
      renderChildren(node.children, depth + 1, {}, out);
    }
  }
}

export function toText(tree) {
  if (!tree || tree.tag !== 'act') {
    throw new TypeError('toText expects a parsed <act> tree');
  }
  const out = [`ACT ${tree.attrs.id}`];
  let secCounter = 0;
  for (const sec of tree.children) {
    if (sec.tag !== 'sec') continue;
    secCounter++;
    const n = sec.attrs.n || String(secCounter);
    const head = sec.children.find((c) => c.tag === 'h');
    out.push('');
    out.push(`${n}. ${head ? head.text : ''}`.trimEnd());
    renderChildren(sec.children, 0, {}, out);
  }
  return out.join('\n') + '\n';
}

