import test from 'node:test';
import assert from 'node:assert/strict';
import { parseAct, toText, ActParseError } from './parse_act.mjs';

const SAMPLE = `<act id="HRA-1998">
<sec n="1"><h>Short Title</h><p>This Act may be cited as the Halvern Records Act.</p></sec>
<sec n="2"><h>Duties</h><p>A custodian shall retain records.</p><sub n="a"><p>Retention runs five years.</p></sub></sec>
</act>
`;

const SAMPLE_TREE = {
  tag: 'act',
  attrs: { id: 'HRA-1998' },
  children: [
    {
      tag: 'sec',
      attrs: { n: '1' },
      children: [
        { tag: 'h', text: 'Short Title' },
        { tag: 'p', text: 'This Act may be cited as the Halvern Records Act.' },
      ],
    },
    {
      tag: 'sec',
      attrs: { n: '2' },
      children: [
        { tag: 'h', text: 'Duties' },
        { tag: 'p', text: 'A custodian shall retain records.' },
        {
          tag: 'sub',
          attrs: { n: 'a' },
          children: [{ tag: 'p', text: 'Retention runs five years.' }],
        },
      ],
    },
  ],
};

const GOLDEN = `ACT HRA-1998

1. Short Title
This Act may be cited as the Halvern Records Act.

2. Duties
A custodian shall retain records.
(a) Retention runs five years.
`;

function expectParseError(src, re) {
  assert.throws(() => parseAct(src), (err) => {
    assert.ok(err instanceof ActParseError, 'expected an ActParseError');
    assert.match(err.message, re);
    return true;
  });
}

test('sample document parses to the exact JSON tree', () => {
  const tree = parseAct(SAMPLE);
  assert.deepStrictEqual(tree, SAMPLE_TREE);
});

test('toText renders the golden plain-text statute', () => {
  const tree = parseAct(SAMPLE);
  assert.strictEqual(toText(tree), GOLDEN);
});

test('unclosed tag reports line and tag name', () => {
  const src = `<act id="X">
<sec n="1"><h>T</h>
<p>body</p>
`;
  // <sec> is opened on line 2 and never closed at EOF.
  expectParseError(src, /^Line 2: unclosed <sec>$/);
});

test('wrong closing tag reports line and both tag names', () => {
  const src = `<act id="X">
<sec n="1"><h>T</h><p>body</sub></sec>
</act>
`;
  expectParseError(src, /^Line 2: mismatched closing tag <\/sub>, expected <\/sec>$/);
});

test('mismatched act-level closer reports line and both names', () => {
  const src = `<act id="X">
<sec n="1"><h>T</h></sec>
<wrong/>
</act>
`;
  // unknown tag caught first — use a known tag closed wrongly instead:
  const src2 = `<act id="X">
<sec n="1"><h>T</h></sec>
</sec>
`;
  expectParseError(src, /unknown tag/);
  expectParseError(src2, /^Line 3: mismatched closing tag <\/sec>, expected <\/act>$/);
});

test('angle-free ampersands are preserved verbatim', () => {
  const src = '<act id="AMP"><sec n="1"><h>T</h><p>A & B — Q &amp-less, raw & only.</p></sec></act>';
  const tree = parseAct(src);
  assert.strictEqual(
    tree.children[0].children[1].text,
    'A & B — Q &amp-less, raw & only.'
  );
  const text = toText(tree);
  assert.ok(text.includes('A & B — Q &amp-less, raw & only.'));
});

test('sub nesting to depth 3 is accepted', () => {
  const src = `<act id="D">
<sec n="1"><h>H</h>
<sub n="a"><p>one</p>
<sub n="i"><p>two</p>
<sub n="A"><p>three</p></sub>
</sub>
</sub>
</sec>
</act>
`;
  const tree = parseAct(src);
  const sub1 = tree.children[0].children[1];
  const sub2 = sub1.children[1];
  const sub3 = sub2.children[1];
  assert.deepStrictEqual(
    [sub1.tag, sub2.tag, sub3.tag],
    ['sub', 'sub', 'sub']
  );
  assert.strictEqual(sub3.children[0].text, 'three');
  const rendered = toText(tree);
  assert.ok(rendered.includes('(a)\n  one\n  (i)\n    two\n    (A)\n      three'));
});

test('sub nesting deeper than depth 3 is an error with position', () => {
  const src = `<act id="D">
<sec n="1"><h>H</h>
<sub n="a"><p>one</p>
<sub n="i"><p>two</p>
<sub n="A"><p>three</p>
<sub n="1"><p>four</p></sub>
</sub>
</sub>
</sub>
</sec>
</act>
`;
  expectParseError(src, /^Line 6: <sub> nesting exceeds maximum depth of 3$/);
});

